export function versionParts(n){const r=String(n||"").match(/^v?(\d{1,5}(?:\.\d{1,5}){0,3})$/i);return r?r[1].split(".").map(Number):null}export function compareVersions(n,r){const t=versionParts(n),e=versionParts(r);if(!t||!e)return null;for(let n=0;n<Math.max(t.length,e.length);n++){const r=(t[n]||0)-(e[n]||0);if(r)return Math.sign(r)}return 0}export function updateStatus(n,r){const t=1===compareVersions(r?.version,n);return{version:r?.version||null,available:t}}